   const text=document.createElement('p');text.textContent=operation==='restore'?'Восстановить «'+info.name+'» в папку «'+info.folder+'»? Недостающие папки будут созданы.':'Окончательно удалить «'+info.name+'» и все её копии в удалённом? Восстановление через эту вкладку станет невозможно.';
   const cancel=document.createElement('button'),accept=document.createElement('button');cancel.textContent='Отмена';accept.textContent=operation==='restore'?'Восстановить':'Удалить навсегда';
