/* Shared model update state for the home screen and native Data panel. */
(function(){
 if(window.localCloudCheckOpen)return;
 const token="e525e47215482f8eb857f153ff9e19c291bbb6a9d82060cb9b8812c257e6e077",port=47832;
 let availability={checking:false,items:[]},lastRunning=false,active=false,lastRevision=null;
 let localFiles=new Set(),localFilesBusy=false;
 const panes=new Set(),key=v=>String(v||'').replace(/\\/g,'/').toLowerCase();
 const local=v=>/^[a-z]:[\\/]/i.test(String(v||''));
 async function httpCall(data){const r=await fetch('http://127.0.0.1:'+port+'/models',{method:'POST',headers:{'Content-Type':'application/json','X-Local-Token':token},body:JSON.stringify(data)});const x=await r.json();if(!x.ok)throw Error(x.error||'Ошибка синхронизации');return x}
 async function nativeCall(data){
  const encoded=btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(data))));
  const source='import os,pathlib,sys;sys.path.insert(0,str(pathlib.Path(os.environ["APPDATA"])/"Autodesk"/"Autodesk Fusion 360"/"API"/"AddIns"/"LocalFolders"));import SyncBridge;print(SyncBridge.encoded('+JSON.stringify(encoded)+'))';
  const raw=await window.neutronJavaScriptObject.executeQuery('executeTextCommandWithoutOutput','Python.Run '+JSON.stringify(source));
  const text=typeof raw==='string'?raw:JSON.stringify(raw),match=text.match(/LOCAL_SYNC_RESULT:(\{[^\r\n]*\})/);
  if(!match)throw Error('Локальный обработчик не ответил. Повторите открытие модели.');
  const result=JSON.parse(match[1]);if(!result.ok)throw Error(result.error);return result;
 }
 async function call(data){
  if(!(window.neutron&&neutron.dashboard&&window.neutronJavaScriptObject))return httpCall(data);
  let result=await nativeCall(data);
  if(result.job){const job=result.job;for(let n=0;n<600;n++){await new Promise(r=>setTimeout(r,200));result=await nativeCall({operation:'cloud-open-result',job});if(!result.pending)return result}throw Error('Проверка сервера ещё выполняется. Повторите открытие позже.');}
  return result;
 }


 function applyLocalFiles(pane){for(const item of pane._lastReturnedData?.all||[]){if(localFiles.has(key(item.id))&&!item.isFolder){item.existsOnLocal=true;item.contentAvailable=true;}}}
 async function refreshLocalFiles(){
  if(localFilesBusy||!(window.neutron&&neutron.dashboard&&window.neutronJavaScriptObject))return;
  localFilesBusy=true;
  try {const result=await nativeCall({operation:'cloud-local-files'});const next=new Set(result.ids.map(key));const changed=next.size!==localFiles.size||[...next].some(id=>!localFiles.has(id));localFiles=next;
   if(changed)for(const pane of panes){applyLocalFiles(pane);pane._update();}
  }catch(e){}finally{localFilesBusy=false;}
 }
 function notice(text){let n=document.getElementById('localSyncNotice');if(!n){n=document.createElement('div');n.id='localSyncNotice';n.setAttribute('role','alert');n.style.cssText='position:fixed;left:12px;right:12px;bottom:42px;background:#604536;color:white;padding:14px;z-index:2147483646;cursor:pointer';n.onclick=()=>n.remove();document.body.append(n)}n.textContent=text}
 window.localCloudCheckOpen=async function(id){if(!local(id))return true;try{await call({operation:'cloud-check-open',id});return true}catch(e){notice(e.message);return false}};
 function state(id){return availability.checking&&local(id)?{blocked:true,message:'Проверка и обновление с сервера…'}:availability.items.find(x=>key(x.id)===key(id))}
 function mark(el,id){if(!el)return;const s=state(id),blocked=!!(s&&s.blocked);el.classList.toggle('localSyncBlocked',blocked);if(blocked){el.setAttribute('data-sync-blocked','1');el.setAttribute('aria-disabled','true');el.setAttribute('data-sync-message',s.message||'Обновляется с сервера…')}else if(el.hasAttribute('data-sync-blocked')){el.removeAttribute('data-sync-blocked');el.removeAttribute('aria-disabled');el.removeAttribute('data-sync-message')}}
 function modelId(props,depth=0){if(!props||typeof props!=='object'||depth>2)return null;for(const k of ['id','fileUri','extUrn','urn'])if(local(props[k]))return props[k];for(const k of ['item','data','model','document','resource','entity']){const found=modelId(props[k],depth+1);if(found)return found}return null}
 function paint(){
  for(const pane of panes)for(const id of Object.keys(pane._designsHtmlElements||{}))mark(pane._designsHtmlElements[id],id);
  document.querySelectorAll('[data-sync-id],[data-row-id],[data-id],button,[role="row"],[role="gridcell"],article').forEach(el=>{
   let id=el.getAttribute('data-sync-id')||el.getAttribute('data-row-id')||el.getAttribute('data-id');
   if(!local(id)){const slot=Object.keys(el).find(k=>k.startsWith('__reactFiber$'));let fiber=slot&&el[slot];for(let n=0;fiber&&n<7;n++,fiber=fiber.return){id=modelId(fiber.memoizedProps);if(id)break}}
   if(local(id))mark(el,id);
  });
 }
 const style=document.createElement('style');style.textContent='.localSyncBlocked{filter:grayscale(1)!important;opacity:.42!important;cursor:wait!important}#localSyncProgress{position:fixed;bottom:0;left:0;right:0;padding:5px 9px;background:#303a48;color:#eef3f8;font:11px Arial;z-index:2147483645}#localSyncProgress progress{display:block;width:100%;height:5px;accent-color:#36a5dc}';document.head.append(style);
 document.addEventListener('dblclick',e=>{const row=e.target.closest('[data-sync-blocked]');if(row){e.preventDefault();e.stopImmediatePropagation();notice(row.getAttribute('data-sync-message'))}},true);
 if(window.neutron&&neutron.dashboard){const proto=neutron.dashboard.panes.Designs.prototype,update=proto._update,open=proto.openDocumentCommonPath;proto._update=function(){panes.add(this);applyLocalFiles(this);const r=update.apply(this,arguments);paint();return r};proto.openDocumentCommonPath=async function(id,b,c,d,done){if(!await window.localCloudCheckOpen(id)){if(done)done(false);return}return open.apply(this,arguments)}}
 async function poll(){if(active)return;active=true;try{const s=await call({operation:'cloud-status'});availability=s.availability||{checking:false,items:[]};if(!availability.checking&&(s.status==='offline'||s.status==='disconnected'||s.status==='revoked'))availability={checking:false,items:[]};paint();const p=s.sync||{};let bar=document.getElementById('localSyncProgress');if(p.running||availability.checking){if(!bar){bar=document.createElement('div');bar.id='localSyncProgress';bar.append(document.createElement('span'),document.createElement('progress'));document.body.append(bar)}bar.firstChild.textContent=[p.stage,p.filename].filter(Boolean).join(': ')||'Проверка моделей…';const meter=bar.lastChild;meter.max=100;if(p.bytesTotal)meter.value=100*p.bytes/p.bytesTotal;else meter.removeAttribute('value')}else if(bar)bar.remove();if((lastRunning&&!p.running)||(lastRevision!==null&&lastRevision!==s.catalogRevision)){window.dispatchEvent(new Event('local-sync-finished'));for(const pane of panes)if(pane.refreshCurrentFolder)pane.refreshCurrentFolder(null,true,null,true)}lastRevision=s.catalogRevision;lastRunning=!!p.running}catch(e){}finally{active=false}}
 setInterval(poll,700);poll();setInterval(refreshLocalFiles,5000);refreshLocalFiles();
})();
